const CTR_FR_U = ['zéro', 'un', 'deux', 'trois', 'quatre', 'cinq', 'six', 'sept', 'huit', 'neuf', 'dix', 'onze', 'douze', 'treize', 'quatorze', 'quinze', 'seize'];
const CTR_FR_T = ['', '', 'vingt', 'trente', 'quarante', 'cinquante', 'soixante'];
/** Montant en lettres (français, orthographe traditionnelle du modèle : « trois mille deux cents ») */
function ctrFrWords(n) {
  n = Math.floor(Math.abs(+n || 0));
  const u99 = x => {
    if (x < 17) return CTR_FR_U[x];
    if (x < 20) return 'dix-' + CTR_FR_U[x - 10];
    if (x < 70) { const t = Math.floor(x / 10), u = x % 10; return CTR_FR_T[t] + (u === 0 ? '' : u === 1 ? ' et un' : '-' + CTR_FR_U[u]); }
    if (x < 80) return x === 71 ? 'soixante et onze' : 'soixante-' + u99(x - 60);
    return x === 80 ? 'quatre-vingts' : 'quatre-vingt-' + u99(x - 80);
  };
  const u999 = (x, inner) => {   // inner : suivi de « mille » (pas de s à cents / vingts)
    const c = Math.floor(x / 100), r = x % 100;
    let w = c === 0 ? '' : c === 1 ? 'cent' : CTR_FR_U[c] + ' cent' + (r === 0 && !inner ? 's' : '');
    if (r) w += (w ? ' ' : '') + u99(r);
    if (inner && r === 80) w = w.replace(/quatre-vingts$/, 'quatre-vingt');
    return w;
  };
  if (n === 0) return 'zéro';
  const parts = [], m = Math.floor(n / 1e6), k = Math.floor(n / 1000) % 1000, r = n % 1000;
  if (m) parts.push(m === 1 ? 'un million' : u999(m) + ' millions');
  if (k) parts.push(k === 1 ? 'mille' : u999(k, true) + ' mille');
  if (r) parts.push(u999(r));
  return parts.join(' ');
}

const CTR_AR_U = ['', 'واحد', 'اثنان', 'ثلاثة', 'أربعة', 'خمسة', 'ستة', 'سبعة', 'ثمانية', 'تسعة'];
const CTR_AR_T = ['', 'عشرة', 'عشرون', 'ثلاثون', 'أربعون', 'خمسون', 'ستون', 'سبعون', 'ثمانون', 'تسعون'];
const CTR_AR_H = ['', 'مائة', 'مائتان', 'ثلاثمائة', 'أربعمائة', 'خمسمائة', 'ستمائة', 'سبعمائة', 'ثمانمائة', 'تسعمائة'];
/** Montant en lettres (arabe) et forme du mot « درهم » qui suit : { words, noun } ; « ثلاثة آلاف ومائتا (3.200) درهم » comme le modèle */
function ctrArWords(n) {
  n = Math.floor(Math.abs(+n || 0));
  const u99 = x => {
    if (x < 10) return CTR_AR_U[x];
    if (x === 10) return 'عشرة';
    if (x === 11) return 'أحد عشر';
    if (x === 12) return 'اثنا عشر';
    if (x < 20) return CTR_AR_U[x - 10] + ' عشر';
    const t = Math.floor(x / 10), u = x % 10;
    return u ? CTR_AR_U[u] + ' و' + CTR_AR_T[t] : CTR_AR_T[t];
  };
  const u999 = (x, last) => {   // last : suivi directement du nom compté (مائتا au lieu de مائتان)
    const h = Math.floor(x / 100), r = x % 100, p = [];
    if (h) p.push(h === 2 && r === 0 && last ? 'مائتا' : CTR_AR_H[h]);
    if (r) p.push(u99(r));
    return p.join(' و');
  };
  if (n === 0) return { words: 'صفر', noun: 'درهم' };
  if (n >= 1e6) return { words: '', noun: 'درهم' };   // au-delà : saisi à la main
  const k = Math.floor(n / 1000), r = n % 1000, p = [];
  if (k) {
    const kr = k % 100;
    if (k === 1) p.push('ألف');
    else if (k === 2) p.push(r === 0 ? 'ألفا' : 'ألفان');
    else if (kr >= 3 && kr <= 10) p.push(u999(k) + ' آلاف');
    else if (kr >= 11) p.push(u999(k) + ' ألفا');
    else p.push(u999(k, true) + ' ألف');
  }
  if (r) p.push(u999(r, true));
  const last = n % 100;
  return { words: p.join(' و'), noun: last >= 3 && last <= 10 ? 'دراهم' : last >= 11 ? 'درهما' : 'درهم' };
}

/** 3200 -> « 3.200 » (séparateur du modèle) */
function ctrAmount(n) { return String(Math.floor(Math.abs(+n || 0))).replace(/\B(?=(\d{3})+(?!\d))/g, '.'); }
/** 2026-08-31 -> 31/08/2026 */
function ctrDate(s) { const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[3] + '/' + m[2] + '/' + m[1] : String(s || ''); }
const ctrBi = v => v ? (/^[\u0600-\u06FF]/.test(v) ? 'ب' + v : 'بـ ' + v) : '';
const ctrClean = v => String(v == null ? '' : v).replace(/[<>{}]/g, '').replace(/\s+/g, ' ').trim();

/** Valeurs des {champs} : société c, salarié e ; vides = « [à compléter] » visible plutôt qu'un trou */
function ctrFields(c, e) {
  c = c || {}; e = e || {};
  const f = e.civ === 'Mme', rf = c.rep_civ === 'Mme', x = ctrClean, nat = x(e.nat_fr) || 'Marocaine';
  const sal = Math.floor(+e.sal || 0), ar = ctrArWords(sal);
  const v = {
    soc: x(c.name), sigle: x(c.sigle), forme_fr: x(c.forme_fr), forme_ar: x(c.forme_ar), capital: x(c.capital),
    siege_fr: x(c.siege_fr), siege_ar: x(c.siege_ar), rc_ville_fr: x(c.rc_ville_fr), rc_ville_ar: x(c.rc_ville_ar), rc: x(c.rc),
    rep_civ_fr: rf ? 'Madame' : 'Monsieur', rep_civ_ar: rf ? 'السيدة' : 'السيد', bisifa: rf ? 'بصفتها' : 'بصفته',
    rep: x(c.rep_name), rep_ar: x(c.rep_name_ar) || x(c.rep_name),
    rep_qual_fr: x(c.rep_qual_fr) || (rf ? 'Gérante' : 'Gérant'), rep_qual_ar: x(c.rep_qual_ar) || (rf ? 'مسيرة' : 'مسيرا'),
    rh_mail: x(c.rh_mail), rh_tel: x(c.rh_tel), ville_fr: x(c.ville_fr), ville_ar: x(c.ville_ar),
    civ: f ? 'Mme' : 'M.', ne: f ? 'née' : 'né', civ_ar: f ? 'السيدة' : 'السيد', mazdad: f ? 'المزدادة' : 'المزداد',
    hamil: f ? 'الحاملة' : 'الحامل', sakin: f ? 'والساكنة' : 'والساكن', soussigne: f ? 'soussignée' : 'soussigné',
    muwaqqi: f ? 'الموقعة' : 'الموقع', tenu: f ? 'tenue' : 'tenu', saiq: f ? 'سائقة' : 'سائقا',
    nom: x(e.nom), nom_ar: x(e.nom_ar) || x(e.nom), naiss: ctrDate(e.naiss), lieu: x(e.lieu), lieu_ar: x(e.lieu_ar) || x(e.lieu),
    nat_fr: nat, nat_ar: x(e.nat_ar) || (/^marocain/i.test(nat) ? (f ? 'مغربية' : 'مغربي') : ''),
    cin: x(e.cin).toUpperCase(), adresse: x(e.adresse), adresse_ar: x(e.adresse_ar) || x(e.adresse),
    effet: ctrDate(e.effet),
    // « ب » attaché à un mot arabe (بالدار البيضاء), « بـ » devant un mot en lettres latines (بـ Tiznit)
    bi_lieu: ctrBi(x(e.lieu_ar) || x(e.lieu)), bi_adresse: ctrBi(x(e.adresse_ar) || x(e.adresse)), sal: sal ? ctrAmount(sal) : '', sal_fr: x(e.sal_fr) || (sal ? ctrFrWords(sal) : ''),
    sal_ar: x(e.sal_ar) || (sal ? ar.words : ''), dh_ar: sal ? ar.noun : 'درهم', date_sig: ctrDate(e.date_sig)
  };
  return v;
}
/** Champs obligatoires manquants (libellés) : rien n'est inventé, le contrat n'est produit que complet */
function ctrMissing(c, e) {
  const v = ctrFields(c, e), L = [];
  [['soc', 'Société : nom'], ['sigle', 'Société : forme (S.A.R.L…)'], ['forme_fr', 'Société : forme juridique (français)'], ['forme_ar', 'Société : forme juridique (arabe)'],
    ['capital', 'Société : capital'], ['siege_fr', 'Société : siège (français)'], ['siege_ar', 'Société : siège (arabe)'], ['rc_ville_fr', 'Société : ville du registre de commerce'],
    ['rc_ville_ar', 'Société : ville du registre de commerce (arabe)'], ['rc', 'Société : numéro RC'], ['rep', 'Société : dirigeant'],
    ['rh_mail', 'Société : e-mail RH'], ['rh_tel', 'Société : téléphone RH'], ['ville_fr', 'Société : ville de signature'], ['ville_ar', 'Société : ville de signature (arabe)'],
    ['nom', 'Nom et prénom'], ['naiss', 'Date de naissance'], ['lieu', 'Lieu de naissance'], ['nat_ar', 'Nationalité (arabe)'], ['cin', 'N° CIN'],
    ['adresse', 'Adresse'], ['effet', 'Date d\'effet'], ['sal', 'Salaire net'], ['sal_fr', 'Salaire en lettres (français)'], ['sal_ar', 'Salaire en lettres (arabe)']].forEach(([k, l]) => { if (!v[k]) L.push(l); });
  return L;
}

/** Lignes du document (format de ctpBuild) */
function ctrBlocks(c, e) {
  const v = ctrFields(c, e), fill = t => String(t || '').replace(/\{([a-z_]+)\}/g, (m, k) => v[k] != null ? v[k] : m);
  const rows = [];
  CTR_ROWS.forEach(r => {
    // français : espaces insécables avant ; : » et après « (jamais de guillemet seul en fin ou en début de ligne)
    const fr = fill(r.fr).replace(/« /g, '«\u00a0').replace(/ ([»;:?!])/g, '\u00a0$1'), ar = fill(r.ar), P = (t, o) => Object.assign({ t: t }, o || {});
    switch (r.k) {
      case 't': rows.push({ k: 'title', fr: fr, ar: ar }); break;
      case 'pb': rows.push({ k: 'pb' }); break;
      case 'h': rows.push({ fr: P(fr), ar: P(ar, { a: 's' }), next: true }); break;
      case 'H': rows.push({ fr: P('<b>' + fr + '</b>'), ar: P('<b>' + ar + '</b>', { a: 's' }), next: true }); break;
      case 's': rows.push({ fr: P(fr, { a: 's' }), ar: P(ar, { a: 's' }), next: true }); break;
      case 'l': rows.push({ fr: P(fr, { list: '•' }), ar: P(ar, { list: '•' }) }); break;
      case 'L': rows.push({ fr: P(fr, { list: '••' }), ar: P(ar, { list: '••' }) }); break;
      case 'd': rows.push({ fr: P(fr, { list: '-', a: 's' }), ar: P(ar, { list: '-', a: 's' }) }); break;
      case 'i': rows.push({ fr: P(fr, { list: '(i)', label: r.label }), ar: P(ar, { list: '(i)', label: r.label }) }); break;
      case 'a': rows.push({ fr: P(fr, { list: 'A.', label: r.label, a: 's' }), ar: P(ar, { list: 'A.', label: r.label, a: 's' }), next: true }); break;
      case 'c': rows.push({ fr: P('<b>' + fr + '</b>', { a: 'c' }), ar: P('<b>' + ar + '</b>', { a: 'c' }) }); break;
      case 'g': rows.push({ fr: P(fr, { a: 's' }), ar: P(ar, { a: 's' }), before: r.before }); break;
      case 'sig':
        rows.push({ fr: [P('<b>La Société</b>', { a: 's' }), P(fill('{soc} {sigle}'), { a: 's', before: 0 }), P(fill('<i>Représentée par {rep_civ_fr} {rep}</i>'), { a: 's', before: 0 })],
          ar: [P('<b>الشركة</b>', { a: 's' }), P(fill('{soc} {sigle}'), { a: 's', before: 0 }), P(fill('<i>{rep_ar}</i>'), { a: 's', before: 0 })], keep: true, after: 58 });
        rows.push({ fr: [P('<b>Le Salarié</b>', { a: 's' }), P(fill('{nom}'), { a: 's', before: 0 })],
          ar: [P('<b>الأجير</b>', { a: 's' }), P(fill('{nom_ar}'), { a: 's', before: 0 }), P('<b>رقم البطاقة الوطنية للتعريف:</b>', { a: 's', before: 0 }), P(fill('<b>{cin}</b>'), { a: 's', before: 0 })], keep: true });
        break;
      case 'sig2': rows.push({ k: 'space', h: 58 }); break;
      default: rows.push({ fr: P(fr), ar: P(ar) });
    }
    if (r.before != null && rows.length) rows[rows.length - 1].before = r.before;
  });
  return rows;
}

if (typeof module === 'object' && module.exports) module.exports = { CTR_ROWS, ctrFrWords, ctrArWords, ctrAmount, ctrDate, ctrFields, ctrMissing, ctrBlocks };
